import {freshRides,validRides} from './downhill.mjs';
import {validCamp} from './expedition.mjs';
import {exchangeInventory} from './progression.mjs';
export const FISH={trout:{name:'Bachforelle',item:'trout',min:.22,max:1.4,power:.78},char:{name:'Saibling',item:'char',min:.18,max:1.8,power:1},perch:{name:'Egli',item:'perch',min:.12,max:.65,power:.6}};
export const freshActivities=()=>({active:null,camp:null,rides:freshRides(),starterGiven:false,roasts:0,perfect:0,fishCaught:0,bestFish:0,waterCarried:0,orchardDay:0,discoveries:[]});
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),finite=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b,int=(v,a=0,b=1e7)=>Number.isSafeInteger(v)&&v>=a&&v<=b;
export function validActivities(a){if(!a||!validRides(a.rides)||!validCamp(a.camp??null)||typeof a.starterGiven!=='boolean'||!['roasts','perfect','fishCaught','waterCarried','orchardDay'].every(k=>int(a[k]))||a.perfect>a.roasts||!finite(a.bestFish,0,20)||!Array.isArray(a.discoveries)||a.discoveries.length>8||new Set(a.discoveries).size!==a.discoveries.length||!a.discoveries.every(k=>['forest-clearing','hidden-spring','fishing-shore','alp-axe'].includes(k)))return false;const r=a.active;if(r===null)return true;if(!r||!['roast','fishing'].includes(r.kind)||!finite(r.time,0,1e7)||!['playing','result','casting','waiting','bite','reeling','landed','missed','broken','escaped'].includes(r.phase))return false;if(r.kind==='roast')return (r.food===undefined||['marshmallow','trout','char','perch'].includes(r.food))&&['playing','result'].includes(r.phase)&&finite(r.x,0,1)&&finite(r.y,0,1)&&finite(r.rotation,0,Math.PI*2)&&finite(r.heat,0,2)&&['brown','char'].every(k=>Array.isArray(r[k])&&r[k].length===4&&r[k].every(v=>finite(v,0,3)))&&['','perfect','golden','raw','burnt'].includes(r.quality);return Object.hasOwn(FISH,r.species)&&finite(r.size,.1,2)&&finite(r.wait,0,30)&&finite(r.bite,0,3)&&finite(r.distance,0,1)&&finite(r.tension,0,1.1)&&finite(r.slack,0,10)&&finite(r.bobber,0,1)&&['casting','waiting','bite','reeling','landed','missed','broken','escaped'].includes(r.phase)&&(r.cast===undefined||finite(r.cast,0,1))&&(r.bait===undefined||['worm','bread','berry'].includes(r.bait));}
export function startRoast(s,food='marshmallow'){if(s.activities.active)return{ok:false,message:'Beende zuerst die laufende Aktivität.'};if(!['marshmallow','trout','char','perch'].includes(food))return{ok:false,message:'Wähle einen Marshmallow oder gefangenen Fisch.'};const r=exchangeInventory(s,{take:food==='marshmallow'?{marshmallow:1}:{[food]:1,wood:1}});if(!r.ok)return r;s.activities.active={kind:'roast',food,phase:'playing',x:.5,y:.49,rotation:0,brown:[0,0,0,0],char:[0,0,0,0],time:0,heat:0,quality:''};return{ok:true};}
export function stepRoast(r,dt,{x=r.x,y=r.y,turn=false,fireX=.5,fireY=.72}={}){if(r.phase!=='playing')return;r.x=clamp(x,.02,.98);r.y=clamp(y,.08,.92);dt=clamp(dt,0,.05);r.time+=dt;if(turn)r.rotation=(r.rotation+dt*1.8)%(Math.PI*2);const distance=Math.hypot((r.x-fireX)*1.25,r.y-fireY);r.heat=clamp((.34-distance)/.27,0,1.45);const side=Math.floor((r.rotation+Math.PI/4)/(Math.PI/2))%4;r.brown[side]=Math.min(3,r.brown[side]+dt*r.heat*.13);r.char[side]=Math.min(3,r.char[side]+dt*(Math.max(0,r.brown[side]-.91)*.32+Math.max(0,r.heat-1.05)*.28));if(r.char.some(v=>v>=.65)){r.phase='result';r.quality='burnt';}}
export function finishRoast(r){if(r.phase!=='playing')return false;r.phase='result';const min=Math.min(...r.brown),max=Math.max(...r.brown);r.quality=r.char.some(v=>v>.4)||max>1.5?'burnt':min>=.38&&max<=1.05?'perfect':min>=.16&&max<1.4?'golden':'raw';return true;}
export function claimRoast(s){const r=s.activities.active;if(r?.kind!=='roast'||r.phase!=='result')return{ok:false,message:'Nimm den Stock zuerst vom Feuer.'};const fish=r.food&&r.food!=='marshmallow',item=fish?(r.quality==='perfect'||r.quality==='golden'?'grilledFish':r.quality==='raw'?r.food:null):r.quality==='perfect'?'perfectMarshmallow':r.quality==='golden'?'roastedMarshmallow':null;if(item){const q=exchangeInventory(s,{give:{[item]:1}});if(!q.ok)return q;}s.activities.roasts++;if(r.quality==='perfect'&&!fish)s.activities.perfect++;s.activities.active=null;return{ok:true,item,message:item?(fish&&r.quality==='raw'?'Noch nicht gar: Fisch zurück im Rucksack.':'Im Rucksack – du kannst ihn essen oder im Dorf verkaufen.'):r.quality==='burnt'?'Verbrannt: nicht essbar. Beim nächsten Mal öfter drehen.':'Noch roh: diesmal kein fertiger Snack.'};}
export function startFishing(s,species='trout',random=Math.random,options={}){if(s.activities.active||!Object.hasOwn(FISH,species))return{ok:false,message:'Beende zuerst die laufende Aktivität.'};if(!s.inventory.fishingRod)return{ok:false,message:'Nimm die Leihangel oder baue eine Angel an der Werkbank.'};const bait=options.bait||'worm';if(!['worm','bread','berry'].includes(bait))return{ok:false,message:'Unbekannter Köder.'};if(bait!=='worm'){const q=exchangeInventory(s,{take:{[bait]:1}});if(!q.ok)return q;}const fish=FISH[species];s.activities.active={kind:'fishing',species,size:Math.round((fish.min+(fish.max-fish.min)*random())*100)/100,bait,cast:options.cast?0:1,phase:options.cast?'casting':'waiting',time:0,wait:(3+random()*6)*(bait==='berry'&&species==='perch'?.8:1),bite:0,distance:1,tension:.25,slack:0,bobber:.5};if(!s.activities.discoveries.includes('fishing-shore'))s.activities.discoveries.push('fishing-shore');return{ok:true};}
export function hookFish(r){if(r?.kind!=='fishing')return false;if(r.phase==='waiting'){r.phase='missed';return false;}if(r.phase!=='bite')return false;r.phase='reeling';r.tension=.35;r.slack=0;return true;}
export function stepFishing(r,dt,reel=false){dt=clamp(dt,0,.05);if(!['casting','waiting','bite','reeling'].includes(r.phase))return;r.time+=dt;if(r.phase==='casting'){r.cast=Math.min(1,(r.cast||0)+dt*.9);if(r.cast>=1)r.phase='waiting';return;}r.bobber=.5+Math.sin(r.time*1.1)*.014;if(r.phase==='waiting'){r.wait=Math.max(0,r.wait-dt);if(!r.wait){r.phase='bite';r.bite=1.5;}return;}if(r.phase==='bite'){r.bite=Math.max(0,r.bite-dt);r.bobber+=Math.sin(r.time*28)*.025;if(!r.bite)r.phase='missed';return;}const direction=typeof reel==='object'?clamp(reel.direction||0,-1,1):reel?1:0,payout=direction<0;reel=direction>0;const fish=FISH[r.species],sizePower=.75+.5*(r.size-fish.min)/(fish.max-fish.min),pull=fish.power*sizePower*(.35+(.5+.5*Math.sin(r.time*2.8+r.size*3))*.65);r.tension=clamp(r.tension+dt*(reel?.24+pull*.33:payout?-.66+pull*.08:-.38+pull*.1),0,1.1);if(reel)r.distance=clamp(r.distance-dt*(.065/(.7+fish.power))*(r.tension>.15?1:.3),0,1);else r.distance=clamp(r.distance+dt*(payout?.024:.011)*pull,0,1);r.slack=r.tension<.08?r.slack+dt:Math.max(0,r.slack-dt*.5);if(r.tension>=1)r.phase='broken';else if(r.slack>3.5)r.phase='escaped';else if(r.distance<=0)r.phase='landed';}
export function claimFish(s){const r=s.activities.active;if(r?.kind!=='fishing'||r.phase!=='landed')return{ok:false,message:'Noch kein Fisch am Ufer.'};const q=exchangeInventory(s,{give:{[FISH[r.species].item]:1}});if(!q.ok)return q;s.activities.fishCaught++;s.activities.bestFish=Math.max(s.activities.bestFish,r.size);s.activities.active=null;return{ok:true,message:FISH[r.species].name+' · '+r.size.toFixed(2)+' kg im Rucksack.'};}
export function cancelActivity(s){s.activities.active=null;}

export function campWelcome(s){if(s.activities.starterGiven)return{ok:false,message:'Das Willkommenspäckli hast du bereits erhalten.'};const r=exchangeInventory(s,{give:{marshmallow:3}});if(r.ok)s.activities.starterGiven=true;return r.ok?{ok:true,message:'Ein Willkommenspäckli: drei Marshmallows für deinen ersten Abend.'}:r;}
